","// Utility functions for working with ServiceNow API field responses
export const display = (field) => {
 if (typeof field === 'string') {
 return field;
 }
 return field?.display_value || '';
};

export const value = (field) => {
 if (typeof field === 'string') {
 return field;
 }
 return field?.value || '';
};","import React, { useState, useEffect } from 'react';
import { display, value } from '../utils/fields.js';

export default function EventList({ onRegister }) {
 const [events, setEvents] = useState([]);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);

 useEffect(() => {
 fetchEvents();
 }, []);

 const fetchEvents = async () => {
 try {
 setLoading(true);
 const response = await fetch(
 '/api/now/table/x_snc_event_maazix_events?sysparm_display_value=all&sysparm_query=status=published^registration_open=true',
 {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 }
 );

 if (!response.ok) {
 throw new Error('Failed to fetch events');
 }

 const data = await response.json();
 setEvents(data.result || []);
 } catch (err) {
 setError(err.message);
 } finally {
 setLoading(false);
 }
 };

 const formatDateTime = (dateTimeStr) => {
 if (!dateTimeStr) return '';
 try {
 return new Date(dateTimeStr).toLocaleString();
 } catch {
 return dateTimeStr;
 }
 };

 if (loading) return <div className="loading">Loading events</div>;
 if (error) return <div className="alert alert-danger">Error: {error}</div>;

 return (
 <div>
 <h2>Available Events</h2>
 <p>Register for upcoming events hosted by our organization.</p>

 {events.length === 0 ? (
 <div className="card">
 <p>No events are currently available for registration.</p>
 </div>
 ) : (
 <div>
 {events.map(event => (
 <div key={value(event.sys_id)} className="card">
 <div className="card-header">
 <h3 className="card-title">{display(event.title)}</h3>
 <div className="card-subtitle">
 Event Code: {display(event.event_code)}
 </div>
 </div>

 <div className="row">
 <div className="col-6">
 <strong>Start:</strong> {formatDateTime(display(event.start_date))}
 </div>
 <div className="col-6">
 <strong>End:</strong> {formatDateTime(display(event.end_date))}
 </div>
 </div>

 {display(event.location) && (
 <div style={{ marginTop: '0.5rem' }}>
 <strong>Location:</strong> {display(event.location)}
 </div>
 )}

 {display(event.description) && (
 <div style={{ marginTop: '0.5rem' }}>
 <strong>Description:</strong> {display(event.description)}
 </div>
 )}

 {display(event.max_attendees) && (
 <div style={{ marginTop: '0.5rem' }}>
 <strong>Maximum Attendees:</strong> {display(event.max_attendees)}
 </div>
 )}

 <div style={{ marginTop: '1rem' }}>
 <button 
 className="btn btn-primary"
 onClick={() => onRegister(value(event.sys_id))}
 >
 Register for Event
 </button>
 </div>
 </div>
 ))}
 </div>
 )}
 </div>
 );
}","import React, { useState, useEffect } from 'react';
import { display, value } from '../utils/fields.js';

export default function GuestRegistration({ eventId, onBack }) {
 const [event, setEvent] = useState(null);
 const [formData, setFormData] = useState({
 first_name: '',
 last_name: '',
 email: '',
 phone: '',
 company: '',
 title: '',
 dietary_restrictions: '',
 special_requirements: ''
 });
 const [loading, setLoading] = useState(true);
 const [submitting, setSubmitting] = useState(false);
 const [error, setError] = useState(null);
 const [success, setSuccess] = useState(false);

 useEffect(() => {
 if (eventId) {
 fetchEvent();
 }
 }, [eventId]);

 const fetchEvent = async () => {
 try {
 setLoading(true);
 const response = await fetch(
 `/api/now/table/x_snc_event_maazix_events/${eventId}?sysparm_display_value=all`,
 {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 }
 );

 if (!response.ok) {
 throw new Error('Event not found');
 }

 const data = await response.json();
 setEvent(data.result);
 } catch (err) {
 setError(err.message);
 } finally {
 setLoading(false);
 }
 };

 const handleInputChange = (e) => {
 const { name, value } = e.target;
 setFormData(prev => ({
 ...prev,
 [name]: value
 }));
 };

 const handleSubmit = async (e) => {
 e.preventDefault();
 setSubmitting(true);
 setError(null);

 try {
 const registrationData = {
 ...formData,
 event: eventId,
 status: 'pending'
 };

 const response = await fetch(
 '/api/now/table/x_snc_event_maazix_registrations?sysparm_display_value=all',
 {
 method: 'POST',
 headers: {
 "Content-Type": "application/json",
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 body: JSON.stringify(registrationData)
 }
 );

 if (!response.ok) {
 const errorData = await response.json();
 throw new Error(errorData.error?.message || 'Registration failed');
 }

 setSuccess(true);
 } catch (err) {
 setError(err.message);
 } finally {
 setSubmitting(false);
 }
 };

 if (loading) return <div className="loading">Loading event details</div>;
 if (error) return <div className="alert alert-danger">Error: {error}</div>;
 if (!event) return <div>Event not found</div>;

 if (success) {
 return (
 <div className="card">
 <h2>Registration Successful!</h2>
 <p>Thank you for registering for <strong>{display(event.title)}</strong>.</p>
 <p>You will receive a confirmation email shortly with event details and next steps.</p>
 <button className="btn btn-primary" onClick={onBack}>
 Back to Events
 </button>
 </div>
 );
 }

 return (
 <div>
 <button className="btn btn-secondary" onClick={onBack} style={{ marginBottom: '1rem' }}>
 ← Back to Events
 </button>

 <div className="card">
 <h2>Register for Event</h2>
 <div className="card-header">
 <h3 className="card-title">{display(event.title)}</h3>
 <div className="card-subtitle">
 {new Date(display(event.start_date)).toLocaleString()} - {new Date(display(event.end_date)).toLocaleString()}
 </div>
 {display(event.location) && <div>Location: {display(event.location)}</div>}
 </div>
 </div>

 <form onSubmit={handleSubmit} className="card">
 <h3>Registration Information</h3>

 <div className="row">
 <div className="col-6">
 <div className="form-group">
 <label className="form-label">First Name *</label>
 <input
 type="text"
 name="first_name"
 className="form-control"
 value={formData.first_name}
 onChange={handleInputChange}
 required
 />
 </div>
 </div>
 <div className="col-6">
 <div className="form-group">
 <label className="form-label">Last Name *</label>
 <input
 type="text"
 name="last_name"
 className="form-control"
 value={formData.last_name}
 onChange={handleInputChange}
 required
 />
 </div>
 </div>
 </div>

 <div className="row">
 <div className="col-6">
 <div className="form-group">
 <label className="form-label">Email Address *</label>
 <input
 type="email"
 name="email"
 className="form-control"
 value={formData.email}
 onChange={handleInputChange}
 required
 />
 </div>
 </div>
 <div className="col-6">
 <div className="form-group">
 <label className="form-label">Phone Number</label>
 <input
 type="tel"
 name="phone"
 className="form-control"
 value={formData.phone}
 onChange={handleInputChange}
 />
 </div>
 </div>
 </div>

 <div className="row">
 <div className="col-6">
 <div className="form-group">
 <label className="form-label">Company</label>
 <input
 type="text"
 name="company"
 className="form-control"
 value={formData.company}
 onChange={handleInputChange}
 />
 </div>
 </div>
 <div className="col-6">
 <div className="form-group">
 <label className="form-label">Job Title</label>
 <input
 type="text"
 name="title"
 className="form-control"
 value={formData.title}
 onChange={handleInputChange}
 />
 </div>
 </div>
 </div>

 <div className="form-group">
 <label className="form-label">Dietary Restrictions</label>
 <textarea
 name="dietary_restrictions"
 className="form-control"
 value={formData.dietary_restrictions}
 onChange={handleInputChange}
 placeholder="Please specify any dietary restrictions or allergies"
 />
 </div>

 <div className="form-group">
 <label className="form-label">Special Requirements</label>
 <textarea
