 >
 Cancel
 </button>
 </div>
 </form>
 </div>
 );
}","import React, { useState, useEffect } from 'react';
import { display, value } from '../utils/fields.js';

export default function EventManagement() {
 const [events, setEvents] = useState([]);
 const [selectedEvent, setSelectedEvent] = useState(null);
 const [registrations, setRegistrations] = useState([]);
 const [groups, setGroups] = useState({
 unassigned: [],
 group_a: [],
 group_b: [],
 group_c: []
 });
 const [loading, setLoading] = useState(true);
 const [draggedItem, setDraggedItem] = useState(null);

 useEffect(() => {
 fetchEvents();
 }, []);

 useEffect(() => {
 if (selectedEvent) {
 fetchRegistrations();
 }
 }, [selectedEvent]);

 useEffect(() => {
 organizeRegistrationsByGroup();
 }, [registrations]);

 const fetchEvents = async () => {
 try {
 const response = await fetch(
 '/api/now/table/x_snc_event_maazix_events?sysparm_display_value=all&sysparm_query=ORDERBYDESCstart_date',
 {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 }
 );
 const data = await response.json();
 setEvents(data.result || []);
 if (data.result && data.result.length > 0) {
 setSelectedEvent(value(data.result[0].sys_id));
 }
 } catch (err) {
 console.error('Error fetching events:', err);
 } finally {
 setLoading(false);
 }
 };

 const fetchRegistrations = async () => {
 if (!selectedEvent) return;

 try {
 const response = await fetch(
 `/api/now/table/x_snc_event_maazix_registrations?sysparm_display_value=all&sysparm_query=event=${selectedEvent}^status!=cancelled`,
 {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 }
 );
 const data = await response.json();
 setRegistrations(data.result || []);
 } catch (err) {
 console.error('Error fetching registrations:', err);
 }
 };

 const organizeRegistrationsByGroup = () => {
 const newGroups = {
 unassigned: [],
 group_a: [],
 group_b: [],
 group_c: []
 };

 registrations.forEach(reg => {
 const groupAssignment = display(reg.group_assignment);
 if (groupAssignment === 'Group A') {
 newGroups.group_a.push(reg);
 } else if (groupAssignment === 'Group B') {
 newGroups.group_b.push(reg);
 } else if (groupAssignment === 'Group C') {
 newGroups.group_c.push(reg);
 } else {
 newGroups.unassigned.push(reg);
 }
 });

 setGroups(newGroups);
 };

 const handleDragStart = (e, registration) => {
 setDraggedItem(registration);
 e.dataTransfer.effectAllowed = 'move';
 };

 const handleDragOver = (e) => {
 e.preventDefault();
 e.dataTransfer.dropEffect = 'move';
 };

 const handleDragEnter = (e) => {
 e.preventDefault();
 e.currentTarget.classList.add('drag-over');
 };

 const handleDragLeave = (e) => {
 e.currentTarget.classList.remove('drag-over');
 };

 const handleDrop = async (e, targetGroup) => {
 e.preventDefault();
 e.currentTarget.classList.remove('drag-over');

 if (!draggedItem) return;

 const groupMapping = {
 'unassigned': '',
 'group_a': 'Group A',
 'group_b': 'Group B',
 'group_c': 'Group C'
 };

 try {
 await fetch(
 `/api/now/table/x_snc_event_maazix_registrations/${value(draggedItem.sys_id)}`,
 {
 method: 'PATCH',
 headers: {
 "Content-Type": "application/json",
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 body: JSON.stringify({
 group_assignment: groupMapping[targetGroup]
 })
 }
 );

 // Refresh registrations to reflect the change
 fetchRegistrations();
 } catch (err) {
 console.error('Error updating group assignment:', err);
 }

 setDraggedItem(null);
 };

 const RegistrationCard = ({ registration }) => (
 <div
 className="draggable-item"
 draggable
 onDragStart={(e) => handleDragStart(e, registration)}
 >
 <div style={{ fontWeight: 'bold' }}>
 {display(registration.first_name)} {display(registration.last_name)}
 </div>
 <div style={{ fontSize: '0.9rem', color: 'var(--text-secondary)' }}>
 {display(registration.email)}
 </div>
 {display(registration.company) && (
 <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>
 {display(registration.company)}
 </div>
 )}
 <div style={{ marginTop: '0.5rem' }}>
 <span className={`badge badge-${display(registration.status)}`}>
 {display(registration.status)}
 </span>
 </div>
 </div>
 );

 if (loading) return <div className="loading">Loading events</div>;

 return (
 <div>
 <h2>Event Management</h2>

 <div className="form-group">
 <label className="form-label">Select Event:</label>
 <select 
 className="form-control"
 value={selectedEvent || ''}
 onChange={(e) => setSelectedEvent(e.target.value)}
 >
 <option value="">Select an event...</option>
 {events.map(event => (
 <option key={value(event.sys_id)} value={value(event.sys_id)}>
 {display(event.title)} - {new Date(display(event.start_date)).toLocaleDateString()}
 </option>
 ))}
 </select>
 </div>

 {selectedEvent && (
 <div>
 <h3>Registrations ({registrations.length} total)</h3>
 <p>Drag and drop registrations between groups to organize attendees for targeted communications.</p>

 <div className="drag-container">
 <div 
 className="drag-column"
 onDragOver={handleDragOver}
 onDragEnter={handleDragEnter}
 onDragLeave={handleDragLeave}
 onDrop={(e) => handleDrop(e, 'unassigned')}
 >
 <h3>Unassigned ({groups.unassigned.length})</h3>
 {groups.unassigned.map(reg => (
 <RegistrationCard key={value(reg.sys_id)} registration={reg} />
 ))}
 </div>

 <div 
 className="drag-column"
 onDragOver={handleDragOver}
 onDragEnter={handleDragEnter}
 onDragLeave={handleDragLeave}
 onDrop={(e) => handleDrop(e, 'group_a')}
 >
 <h3>Group A ({groups.group_a.length})</h3>
 {groups.group_a.map(reg => (
 <RegistrationCard key={value(reg.sys_id)} registration={reg} />
 ))}
 </div>

 <div 
 className="drag-column"
 onDragOver={handleDragOver}
 onDragEnter={handleDragEnter}
 onDragLeave={handleDragLeave}
 onDrop={(e) => handleDrop(e, 'group_b')}
 >
 <h3>Group B ({groups.group_b.length})</h3>
 {groups.group_b.map(reg => (
 <RegistrationCard key={value(reg.sys_id)} registration={reg} />
 ))}
 </div>

 <div 
 className="drag-column"
 onDragOver={handleDragOver}
 onDragEnter={handleDragEnter}
 onDragLeave={handleDragLeave}
 onDrop={(e) => handleDrop(e, 'group_c')}
 >
 <h3>Group C ({groups.group_c.length})</h3>
 {groups.group_c.map(reg => (
 <RegistrationCard key={value(reg.sys_id)} registration={reg} />
 ))}
 </div>
 </div>
 </div>
 )}
 </div>
 );
}","/* CSS Custom Properties for Corporate Colors and Dark Mode */
:root {
 /* Corporate Colors - Light Mode */
 --primary-color: #0066cc;
 --secondary-color: #003d7a;
 --accent-color: #ff6b35;
 --success-color: #28a745;
 --warning-color: #ffc107;
 --error-color: #dc3545;

 /* Background Colors */
 --bg-primary: #ffffff;
 --bg-secondary: #f8f9fa;
 --bg-tertiary: #e9ecef;

 /* Text Colors */
 --text-primary: #212529;
 --text-secondary: #6c757d;
 --text-light: #ffffff;

 /* Border Colors */
 --border-color: #dee2e6;
 --border-focus: var(--primary-color);

 /* Shadows */
 --shadow-sm: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);
 --shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
 --shadow-lg: 0 1rem 3rem rgba(0, 0, 0, 0.175);
}

/* Dark Mode */
[data-theme="dark"] {
 --primary-color: #4da6ff;
 --secondary-color: #66b2ff;
 --accent-color: #ff8c69;

 --bg-primary: #1a1a1a;
 --bg-secondary: #2d2d2d;
 --bg-tertiary: #404040;

 --text-primary: #ffffff;
 --text-secondary: #b8b8b8;
 --text-light: #ffffff;

 --border-color: #404040;
 --shadow-sm: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.3);
 --shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.4);
 --shadow-lg: 0 1rem 3rem rgba(0, 0, 0, 0.5);
}

/* Auto Dark Mode Detection */
@media (prefers-color-scheme: dark) {
 :root:not([data-theme="light"]) {
 --primary-color: #4da6ff;
 --secondary-color: #66b2ff;
 --accent-color: #ff8c69;

 --bg-primary: #1a1a1a;
 --bg-secondary: #2d2d2d;
 --bg-tertiary: #404040;

 --text-primary: #ffffff;
 --text-secondary: #b8b8b8;
 --text-light: #ffffff;

 --border-color: #404040;
 --shadow-sm: 0 0.125rem 0.25rem rgba(0, 0, 0, 0.3);
 --shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.4);
 --shadow-lg: 0 1rem 3rem rgba(0, 0, 0, 0.5);
 }
}

/* Base Styles */
* {
 box-sizing: border-box;
}

body {
 margin: 0;
 padding: 0;
 font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
 background-color: var(--bg-primary);
 color: var(--text-primary);
 transition: background-color 0.3s ease, color 0.3s ease;
}

.app {
 min-height: 100vh;
 display: flex;
 flex-direction: column;
}

/* Navigation */
.app-nav {
 background-color: var(--bg-secondary);
 border-bottom: 1px solid var(--border-color);
 padding: 1rem 2rem;
 display: flex;
 justify-content: space-between;
 align-items: center;
 box-shadow: var(--shadow-sm);
}

.nav-brand {
