 gap: 0.5rem;
}

.admin-badge {
 background-color: var(--accent-color);
 color: var(--text-light);
 padding: 0.2rem 0.5rem;
 border-radius: 0.25rem;
 font-size: 0.75rem;
 font-weight: 600;
 text-transform: uppercase;
}

.guest-badge {
 background-color: var(--warning-color);
 color: var(--text-primary);
 padding: 0.2rem 0.5rem;
 border-radius: 0.25rem;
 font-size: 0.75rem;
 font-weight: 600;
 text-transform: uppercase;
}

.nav-links {
 display: flex;
 gap: 1rem;
}

.nav-links button {
 background: none;
 border: none;
 padding: 0.5rem 1rem;
 border-radius: 0.25rem;
 cursor: pointer;
 color: var(--text-primary);
 font-weight: 500;
 transition: all 0.2s ease;
}

.nav-links button:hover {
 background-color: var(--bg-tertiary);
}

.nav-links button.active {
 background-color: var(--primary-color);
 color: var(--text-light);
}

/* Main Content */
.app-main {
 flex: 1;
 padding: 2rem;
 max-width: 1200px;
 margin: 0 auto;
 width: 100%;
}

/* Access Denied */
.access-denied {
 text-align: center;
 padding: 2rem;
 background-color: var(--bg-secondary);
 border-radius: 0.5rem;
 border: 1px solid var(--border-color);
 margin: 2rem auto;
 max-width: 600px;
}

.access-denied h2 {
 color: var(--error-color);
 margin-bottom: 1rem;
}

.access-denied button {
 background-color: var(--primary-color);
 color: var(--text-light);
 border: none;
 padding: 0.5rem 1rem;
 border-radius: 0.25rem;
 cursor: pointer;
 font-weight: 500;
 margin-top: 1rem;
}

/* Cards */
.card {
 background-color: var(--bg-secondary);
 border: 1px solid var(--border-color);
 border-radius: 0.5rem;
 padding: 1.5rem;
 margin-bottom: 1.5rem;
 box-shadow: var(--shadow-sm);
 transition: box-shadow 0.2s ease;
}

.card:hover {
 box-shadow: var(--shadow);
}

.card-header {
 margin-bottom: 1rem;
}

.card-title {
 margin: 0 0 0.5rem 0;
 color: var(--primary-color);
 font-size: 1.25rem;
 font-weight: 600;
}

.card-subtitle {
 margin: 0;
 color: var(--text-secondary);
 font-size: 0.9rem;
}

/* Buttons */
.btn {
 display: inline-block;
 padding: 0.5rem 1rem;
 margin: 0.25rem;
 border: none;
 border-radius: 0.25rem;
 cursor: pointer;
 font-size: 0.9rem;
 font-weight: 500;
 text-decoration: none;
 text-align: center;
 transition: all 0.2s ease;
}

.btn-primary {
 background-color: var(--primary-color);
 color: var(--text-light);
}

.btn-primary:hover {
 background-color: var(--secondary-color);
}

.btn-secondary {
 background-color: var(--bg-tertiary);
 color: var(--text-primary);
 border: 1px solid var(--border-color);
}

.btn-secondary:hover {
 background-color: var(--border-color);
}

.btn-success {
 background-color: var(--success-color);
 color: var(--text-light);
}

.btn-warning {
 background-color: var(--warning-color);
 color: var(--text-primary);
}

.btn-danger {
 background-color: var(--error-color);
 color: var(--text-light);
}

/* Forms */
.form-group {
 margin-bottom: 1rem;
}

.form-label {
 display: block;
 margin-bottom: 0.5rem;
 font-weight: 500;
 color: var(--text-primary);
}

.form-control {
 width: 100%;
 padding: 0.5rem 0.75rem;
 border: 1px solid var(--border-color);
 border-radius: 0.25rem;
 background-color: var(--bg-primary);
 color: var(--text-primary);
 font-size: 1rem;
 transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.form-control:focus {
 outline: none;
 border-color: var(--border-focus);
 box-shadow: 0 0 0 0.2rem rgba(0, 102, 204, 0.25);
}

textarea.form-control {
 min-height: 100px;
 resize: vertical;
}

/* Grid Layout */
.row {
 display: flex;
 flex-wrap: wrap;
 margin: -0.5rem;
}

.col {
 flex: 1;
 padding: 0.5rem;
}

.col-auto {
 flex: 0 0 auto;
 padding: 0.5rem;
}

.col-6 {
 flex: 0 0 50%;
 padding: 0.5rem;
}

.col-4 {
 flex: 0 0 33.333333%;
 padding: 0.5rem;
}

.col-3 {
 flex: 0 0 25%;
 padding: 0.5rem;
}

/* Drag and Drop Styles */
.drag-container {
 display: flex;
 gap: 2rem;
 margin: 2rem 0;
}

.drag-column {
 flex: 1;
 min-height: 400px;
 padding: 1rem;
 border: 2px dashed var(--border-color);
 border-radius: 0.5rem;
 background-color: var(--bg-secondary);
 transition: all 0.2s ease;
}

.drag-column.drag-over {
 border-color: var(--primary-color);
 background-color: rgba(0, 102, 204, 0.05);
}

.drag-column h3 {
 margin: 0 0 1rem 0;
 text-align: center;
 color: var(--text-secondary);
}

.draggable-item {
 padding: 0.75rem;
 margin: 0.5rem 0;
 background-color: var(--bg-primary);
 border: 1px solid var(--border-color);
 border-radius: 0.25rem;
 cursor: move;
 transition: all 0.2s ease;
}

.draggable-item:hover {
 box-shadow: var(--shadow-sm);
 transform: translateY(-1px);
}

.draggable-item.dragging {
 opacity: 0.5;
 transform: rotate(5deg);
}

/* Status Badges */
.badge {
 display: inline-block;
 padding: 0.25rem 0.5rem;
 font-size: 0.75rem;
 font-weight: 600;
 border-radius: 0.25rem;
 text-transform: uppercase;
}

.badge-pending {
 background-color: var(--warning-color);
 color: var(--text-primary);
}

.badge-confirmed {
 background-color: var(--success-color);
 color: var(--text-light);
}

.badge-cancelled {
 background-color: var(--error-color);
 color: var(--text-light);
}

.badge-attended {
 background-color: var(--primary-color);
 color: var(--text-light);
}

/* Loading States */
.loading {
 text-align: center;
 padding: 2rem;
 color: var(--text-secondary);
}

.loading::after {
 content: "...";
 animation: dots 1.5s steps(5, end) infinite;
}

@keyframes dots {
 0%, 20% { color: rgba(0,0,0,0); text-shadow: .25em 0 0 rgba(0,0,0,0), .5em 0 0 rgba(0,0,0,0); }
 40% { color: var(--text-secondary); text-shadow: .25em 0 0 rgba(0,0,0,0), .5em 0 0 rgba(0,0,0,0); }
 60% { text-shadow: .25em 0 0 var(--text-secondary), .5em 0 0 rgba(0,0,0,0); }
 80%, 100% { text-shadow: .25em 0 0 var(--text-secondary), .5em 0 0 var(--text-secondary); }
}

/* Responsive Design */
@media (max-width: 768px) {
 .app-nav {
 padding: 0.75rem 1rem;
 flex-direction: column;
 gap: 1rem;
 }

 .nav-brand h1 {
 font-size: 1.25rem;
 }

 .app-main {
 padding: 1rem;
 }

 .drag-container {
 flex-direction: column;
 }

 .row {
 flex-direction: column;
 }

 .col, .col-6, .col-4, .col-3 {
