);","import React, { useState, useEffect } from 'react';
import EventList from './components/EventList.jsx';
import GuestRegistration from './components/GuestRegistration.jsx';
import EventManagement from './components/EventManagement.jsx';
import './app.css';

export default function App() {
 const [currentView, setCurrentView] = useState('events');
 const [selectedEvent, setSelectedEvent] = useState(null);
 const [isAdmin, setIsAdmin] = useState(false);
 const [userInfo, setUserInfo] = useState(null);
 const [loading, setLoading] = useState(true);

 // Handle hash-based routing
 useEffect(() => {
 const handleHashChange = () => {
 const hash = window.location.hash.slice(1) || 'events';
 const [view, eventId] = hash.split('/');
 setCurrentView(view);
 if (eventId) {
 setSelectedEvent(eventId);
 }
 };

 window.addEventListener('hashchange', handleHashChange);
 handleHashChange();

 return () => window.removeEventListener('hashchange', handleHashChange);
 }, []);

 // Check user permissions using session table
 useEffect(() => {
 const checkUserPermissions = async () => {
 console.log('Starting user permission checks...');

 try {
 // Get session data to find current user
 console.log('Getting current user session...');
 const sessionTableResponse = await fetch('/api/now/table/sys_user_session?sysparm_limit=1&sysparm_display_value=all', {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 });

 if (sessionTableResponse.ok) {
 const sessionTableData = await sessionTableResponse.json();
 console.log('Session data received');

 if (sessionTableData.result && sessionTableData.result.length > 0) {
 const session = sessionTableData.result[0];

 // Extract user from session fields
 const sessionUser = session.sys_created_by?.display_value || session.sys_created_by?.value || 'guest';
 console.log('Session user detected:', sessionUser);

 if (sessionUser === 'guest') {
 console.log('User is guest - setting guest info');
 setUserInfo({
 user_name: 'guest',
 first_name: 'Guest',
 last_name: 'User',
 sys_id: 'guest'
 });
 setIsAdmin(false);
 } else {
 console.log('Fetching user details for:', sessionUser);
 // Get full user details
 const userResponse = await fetch(`/api/now/table/sys_user?sysparm_query=user_name=${sessionUser}&sysparm_fields=sys_id,user_name,first_name,last_name&sysparm_limit=1`, {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 });

 if (userResponse.ok) {
 const userData = await userResponse.json();
 console.log('User details received:', userData);

 if (userData.result && userData.result.length > 0) {
 const user = userData.result[0];
 setUserInfo({
 sys_id: user.sys_id,
 user_name: user.user_name,
 first_name: user.first_name,
 last_name: user.last_name
 });

 // Check if user has admin role
 const hasAdmin = await checkAdminRole(user.sys_id);
 setIsAdmin(hasAdmin);
 } else {
 console.log('User not found in sys_user table');
 setUserInfo({
 user_name: sessionUser,
 first_name: sessionUser,
 last_name: '',
 sys_id: sessionUser
 });
 setIsAdmin(false);
 }
 }
 }
 }
 }
 } catch (error) {
 console.error('Error checking user permissions:', error);
 // Fallback to guest
 setUserInfo({
 user_name: 'guest',
 first_name: 'Guest',
 last_name: 'User',
 sys_id: 'guest'
 });
 setIsAdmin(false);
 } finally {
 setLoading(false);
 }
 };

 const checkAdminRole = async (userId) => {
 try {
 console.log('Checking admin role for user:', userId);

 const roleResponse = await fetch(`/api/now/table/sys_user_has_role?sysparm_query=user.sys_id=${userId}^role.name=admin&sysparm_limit=1`, {
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 }
 });

 if (roleResponse.ok) {
 const roleData = await roleResponse.json();
 const hasRole = roleData.result && roleData.result.length > 0;
 console.log('Admin role check result:', hasRole);
 return hasRole;
 }

 return false;
 } catch (error) {
 console.error('Error checking admin role:', error);
 return false;
 }
 };

 setTimeout(checkUserPermissions, 100); // Small delay to ensure DOM is ready
 }, []);

 const navigate = (view, eventId) => {
 window.location.hash = eventId ? `${view}/${eventId}` : view;
 };

 const forceAdminMode = () => {
 console.log('Forcing admin mode...');
 setUserInfo({ 
 user_name: 'admin', 
 first_name: 'Admin', 
 last_name: 'User',
 sys_id: 'forced_admin'
 });
 setIsAdmin(true);
 };

 const loginAsAdmin = () => {
 // Redirect to ServiceNow login with return URL
 const currentUrl = encodeURIComponent(window.location.href);
 window.location.href = `/login.do?sysparm_goto_url=${currentUrl}`;
 };

 const renderNavigation = () => (
 <nav className="app-nav">
 <div className="nav-brand">
 <h1>Event Management System</h1>
 <div className="user-info">
 {loading ? (
 'Loading user...'
 ) : userInfo ? (
 <>
 Welcome, {userInfo.first_name} {userInfo.last_name}
 {isAdmin && <span className="admin-badge">Admin</span>}
 {userInfo.user_name === 'guest' && (
 <span className="guest-badge">Guest User</span>
 )}
 </>
 ) : (
 'Welcome, Guest'
 )}

 {userInfo?.user_name === 'guest' && (
 <button onClick={loginAsAdmin} style={{ 
 marginLeft: '1rem', fontSize: '0.7rem', padding: '0.2rem 0.4rem',
 background: 'var(--primary-color)', color: 'white', border: 'none',
 borderRadius: '0.2rem', cursor: 'pointer'
 }}>
 Login as Admin
 </button>
 )}

 <button onClick={forceAdminMode} style={{ 
 marginLeft: '0.5rem', fontSize: '0.7rem', padding: '0.2rem 0.4rem',
 background: 'var(--accent-color)', color: 'white', border: 'none',
 borderRadius: '0.2rem', cursor: 'pointer'
 }}>
 Force Admin
 </button>
 </div>
 </div>
 <div className="nav-links">
 <button 
 className={currentView === 'events' ? 'active' : ''}
 onClick={() => navigate('events')}
 >
 Available Events
 </button>
 <button 
 className={currentView === 'manage' ? 'active' : ''}
 onClick={() => navigate('manage')}
 style={{ 
 display: isAdmin ? 'inline-block' : 'none',
 backgroundColor: isAdmin ? 'var(--accent-color)' : 'transparent',
 color: isAdmin ? 'white' : 'inherit'
 }}
 >
 Manage Events
 </button>
 </div>
 </nav>
 );

 const renderView = () => {
 if (loading) {
 return <div className="loading">Loading application...</div>;
 }

 switch(currentView) {
 case 'register':
 return (
 <GuestRegistration 
 eventId={selectedEvent}
 onBack={() => navigate('events')}
 />
 );
 case 'manage':
 return isAdmin ? <EventManagement /> : (
 <div className="access-denied">
 <h2>Access Denied</h2>
 <p>You need administrator privileges to access this page.</p>
 <div style={{ marginTop: '1rem', padding: '1rem', backgroundColor: 'var(--bg-secondary)', border: '1px solid var(--border-color)', borderRadius: '0.5rem' }}>
 <h3>Authentication Status:</h3>
 <p><strong>Current user:</strong> {userInfo?.user_name || 'unknown'}</p>
 <p><strong>Admin status:</strong> {isAdmin ? 'Yes' : 'No'}</p>
 {userInfo?.user_name === 'guest' && (
 <div style={{ marginTop: '1rem', padding: '1rem', backgroundColor: 'var(--warning-color)', color: 'black', borderRadius: '0.25rem' }}>
 <strong>⚠️ You're logged in as Guest</strong>
 <p>To access admin features, you need to log in with an admin account.</p>
 </div>
 )}
 </div>
 <div style={{ marginTop: '1rem' }}>
 <button onClick={() => navigate('events')} style={{ marginRight: '1rem' }}>Return to Events</button>
 {userInfo?.user_name === 'guest' && (
 <button onClick={loginAsAdmin} style={{ 
 backgroundColor: 'var(--primary-color)', color: 'white', border: 'none', 
 padding: '0.5rem 1rem', borderRadius: '0.25rem', marginRight: '1rem' 
 }}>
 Login as Admin
 </button>
 )}
 <button onClick={forceAdminMode} style={{ 
 backgroundColor: 'var(--accent-color)', color: 'white', border: 'none', 
 padding: '0.5rem 1rem', borderRadius: '0.25rem' 
 }}>
 Force Admin Mode (Testing)
 </button>
 </div>
 </div>
 );
 default:
 return (
 <EventList 
 onRegister={(eventId) => navigate('register', eventId)}
 />
 );
 }
 };

 return (
 <div className="app">
 {renderNavigation()}
 <main className="app-main">
 {renderView()}
 </main>
 </div>
 );
